#nullable enable // autogenerated

using MVZ2Logic.Definitions;
using MVZ2Logic.Localization;
using MVZ2Logic.Options;
using UnityEngine;

namespace MVZ2Logic.Contents.Options
{
    [AutoOptionWidgetDefinition(LogicOptionWidgetNames.updateSponsors)]
    public class UpdateSponsorsOptionButton : OptionButtonDefinition
    {
        public UpdateSponsorsOptionButton(string nsp, string name) : base(nsp, name)
        {
        }
        public override bool ShouldEnable(IOptionContext context)
        {
            return context is IOptionContextMainmenu;
        }
        public override string GetLabelText(IOptionContext context)
        {
            if (Global.Sponsors.IsUpdatingSponsors())
            {
                return Global.Localization.GetTextParticular(LogicStrings.SPONSORS_UPDATING, LogicStrings.CONTEXT_OPTION_NAME);
            }
            return base.GetLabelText(context);
        }
        public override bool IsInteractable(IOptionContext context)
        {
            if (Global.Sponsors.IsUpdatingSponsors())
                return false;
            return base.IsInteractable(context);
        }
        public override void OnClick(IOptionContext context)
        {
            var nowSeconds = Time.realtimeSinceStartup;
            if (nowSeconds < lastAttemptSeconds + COOLDOWN_SECONDS)
            {
                if (!cooldownPopUpShown)
                {
                    cooldownPopUpShown = true;

                    var msg = Global.Localization.GetText(LogicStrings.SPONSOR_UPDATE_COOLDOWNED);
                    Global.Scene.ShowPopup(msg);
                }
                return;
            }
            lastAttemptSeconds = nowSeconds;
            cooldownPopUpShown = false;

            Global.Sponsors.ForceUpdateSponsors();
            context.UpdateDialog();
        }
        public const float COOLDOWN_SECONDS = 5;
        private static float lastAttemptSeconds;
        private static bool cooldownPopUpShown;
    }
}
